/** The Ukrainian plural: 1 (not 11) → one; 2–4 (not 12–14) → few; else many. */
const form = (count: string, one: string, few: string, many: string) => {
  const c = Number(count);
  const t = c % 10;
  const h = c % 100;
  if (t === 1 && h !== 11) return one;
  return t >= 2 && t <= 4 && (h < 12 || h > 14) ? few : many;
};
const n = (count: string, one: string, few: string, many: string) => `${count} ${form(count, one, few, many)}`;

/** Phrases with a number or a name in them. */
/** The nonlinear solve's and the buckling's messages, translated inside the notes that carry them (S5). */
const S5_MESSAGES: [RegExp, (m: RegExpExecArray) => string][] = [
  [/^Second order: unstable, the loads are past the critical ones \(αcr < 1\)\.$/, () => "Другий порядок: конструкція нестійка, навантаження перевищили критичні (αcr < 1)."],
  [/^A mechanism once 1 members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механізм після ослаблення 1 стрижня: ніщо не утримує вузол ${m[1]} (${m[2]}).`],
  [/^A mechanism once (\d+) members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механізм після ослаблення ${n(m[1], 'стрижня', 'стрижнів', 'стрижнів')}: ніщо не утримує вузол ${m[2]} (${m[3]}).`],
  [/^A mechanism once 1 members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механізм після ослаблення 1 стрижня та відриву ${n(m[1], 'опори', 'опор', 'опор')}: ніщо не утримує вузол ${m[2]} (${m[3]}).`],
  [/^A mechanism once (\d+) members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механізм після ослаблення ${n(m[1], 'стрижня', 'стрижнів', 'стрижнів')} та відриву ${n(m[2], 'опори', 'опор', 'опор')}: ніщо не утримує вузол ${m[3]} (${m[4]}).`],
  [/^A mechanism at node (\S+) \(([^)]*)\)\.$/, (m) => `Механізм у вузлі ${m[1]} (${m[2]}).`],
  [/^The one-way members and supports did not settle: they go back to states already tried\.$/, () => "Односторонні стрижні та опори не встановилися: вони повертаються до станів, які вже перевірялися."],
  [/^Not settled in (\d+) iterations\.$/, (m) => `Немає збіжності після ${n(m[1], 'ітерації', 'ітерацій', 'ітерацій')}.`],
  [/^No buckling under these loads: the geometric stiffness only stiffens\.$/, () => "Втрати стійкості за цих навантажень немає: геометрична жорсткість лише підсилює конструкцію."],
  [/^No buckling mode: the compressed bars are held by what is round them\.$/, () => "Форми втрати стійкості немає: стиснуті стрижні утримуються навколишніми елементами."],
  [/^A mechanism in its last states\.$/, () => "Механізм в останніх станах."],
];
function s5msg(text: string): string {
  for (const [re, f] of S5_MESSAGES) { const x = re.exec(text); if (x) return f(x); }
  return text;
}

/** S5d: the parts of the imperfections', sheeting's and θ notes that vary. */
function s5dSeg(t: string): string {
  const a = /^φ up to 1\/(\d+) along (X|Y)(?: \(m = ([\d.]+)\))?$/.exec(t);
  if (a) return a[3] ? `φ до 1/${a[1]} уздовж ${a[2]} (m = ${a[3]})` : `φ до 1/${a[1]} уздовж ${a[2]}`;
  const b = /^no column along (X|Y)$/.exec(t);
  return b ? `немає колони вздовж ${b[1]}` : t;
}
